// "hello world" of strudel! 
//
// feel free to comment and uncomment each block
// change some notes and numbers!
// only the lowest stack / block of code will run
//
// If you're on PC
//   [ ctrl + shift + backslash / ] to comment lines in and out
//   [ ctrl + return ] to run and update code blocks
//    
// If you're on a macbook: 
//   [ command + backslash / ] to comment lines in and out
//   [ option + return ] to run and update code blocks
//  
// Learn about mini notation, the core logic of this language:
// https://strudel.cc/learn/mini-notation
//
// Feel free to add $: to the beginning of each pattern to produce a complete cacophony!
//
// Borrowed from http://bit.ly/livecode-art-haus
// Originally available on https://strudel.cc/?yS3HYqqeyM2i

// One cycle per second
setcps(1)


// s() plays a sample. There are lots of samples available, click on "learn" -> sounds!

// Drums - bd means bass drum (kick!), sd means snare drum

s("bd sd")

// hh means hi-hats

// s("bd hh sd hh")

// Stacks allow to multiple lines of instruments playing in parallel
// Notice the comma character!
// ~ means silence, *2 means speeding up, /2 slowing down, etc
// ? adds some randomness

// stack(
//   s("<bd bd*2> ~"),
//   s("~ cp ~ cp"),
//   s("hh*8? bd"),
// )

// When an instrument is prepended with :N, means we are choosing one out of multiple sounds for
// that patch
// Struct comes handy with alternating patterns over a sequence
// Masking allows to avoid a sound over some steps of the sequence

// stack(
//   s("~jazz:1 [jazz jazz:1] jazz:5 jazz"),
//   s("~hh"),
//   s("bd sd"),
//   s("~metal metal:1 metal metal:2").gain("0.7").mask("< 1 0 1 0>"),
//   s("~metal:2 metal:1 metal:4 metal:1").gain("0.7").mask("<0 1>"),
//   s("siren").mask("<0 0 0 1>").gain("2.5"), 
//   s("~bd").struct("1 0 0 0 1 0 1 1 0 1"),
// )
  
// s("bd").struct("1 1 0 1 0 0 1") 

// Musical notes are c,d,e,f,g,a,b followed by an octave number
// <> alternates notes over sequence repetitions

// stack(
// "c4!3 e4 f4 <d4 g4>".note(),
// "<48 52 55>".note()
// )


// stack(
//    "c4 d4 e4 <f4 g4>".note().sound("sawtooth"), 
//    "<48 52 55>".note().sound("sax").clip(1)
// )


// @version 1.0

// Simple beat
// Borrowed from http://bit.ly/livecode-art-haus
// originally available on https://strudel.cc/?nhEpIsA5oD9M_CHjWtEOA3oZ
$: s("[bd <hh oh>]*2").bank("tr909").dec(.4)

// Playing with chords!
//
// Borrowed from http://bit.ly/livecode-art-haus
// originally available on https://strudel.cc/?nhEpIsA5oD9M

setcps(1)
stack(
  s("bd*2,~ [cp,sd]").bank('RolandTR909'),
  // chords
  chord("[~ Gm7] ~ [~ Dm7] ~")
  .dict('lefthand').voicing()
  .add(note("0,.1"))
  .s('sawtooth').gain(.8)
  .cutoff(perlin.range(400,3000).slow(8))
  .decay(perlin.range(0.05,.2)).sustain(0)
  .delay(.9).room(1),
)

// @version 1.0

// "Bridge is over" - https://strudel.cc/?rH0YggRYDrIw
// @license CC BY-NC-SA 4.0 https://creativecommons.org/licenses/by-nc-sa/4.0/
// dan remix @by Felix Roos, bassline by BDP - The Bridge Is Over
setcps(1)

samples({mad:'https://freesound.org/data/previews/22/22274_109943-lq.mp3'})
stack(
  stack(
  note("c3*2 [[c3@1.4 bb2] ab2] gb2*2 <[[gb2@1.4 ab2] bb2] gb2>")
    .gain(.2).clip("[.5 1]*2"),
  n("<0 1 2 3 4 3 2 1>")
    .clip(.5)
    .echoWith(8, 1/32, (x,i)=>x.add(n(i)).velocity(Math.pow(.7,i)))
    .scale('c4 whole tone')
    .echo(3, 1/8, .5)
  ).piano(),
  s("mad").slow(2)
).cpm(78).slow(4)
  .pianoroll()


// @version 1.0

// "Jux und tollerei"
// @license CC BY-NC-SA 4.0 https://creativecommons.org/licenses/by-nc-sa/4.0/
// @by Felix Roos
// remix @allisonlu
// Borrowed from http://bit.ly/livecode-art-haus, originally available on https://strudel.cc/?ox208ssxR7cl

// This demo plays around with palindromes, mild visualization effects (colors),
// and some basic sound processing (filters, panning, etc)

// Go an uncomment few lines below
// Feel free to change .pianoroll() with ._pianoroll()

setcps(1)

note("c3 eb3 g3 bb3").palindrome()
.s('sawtooth')
// .jux(x=>x.rev().color('green').s('sawtooth'))
// .off(1/4, x=>x.add(note("<7 12>/2")).slow(2).late(.005).s('triangle'))
// .lpf(sine.range(200,2000).slow(8))
.lpf(rand.range(500,2000))
.lpd("<.5 .25 .1 0>/4")
.lpa(.2).lpenv(-2)
.decay(.05).sustain(0)
.room(.6)
// .delay(.5).delaytime(.1).delayfeedback(.4)
.pianoroll()

// @version 1.0

// "Orbit"
// @license CC BY-NC-SA 4.0 https://creativecommons.org/licenses/by-nc-sa/4.0/
// Gleb P remix of @by Felix Roos
// Borrowed from http://bit.ly/livecode-art-haus, originally available on https://strudel.cc/?rt0rtzTBHxOY
setcps(1)

stack(
    s("bd sd bd:16").bank("RolandTR808")
  .lpf(2000).delay(0.1).room("<0 0.4 0.2>")
  
  ,
  
n("<0 4 3*2>").color('salmon')
.off(1/4, x=>x.add(2).color('green'))
.off(1/2, x=>x.add(6).color('steelblue'))
.scale('F minor')
.echo(4, 1/8, .5)
.clip(.5).gain(0.7)
.sound('piano').gain(0.5).pianoroll()
  )

// @version 1.0

// Borrowed from http://bit.ly/livecode-art-haus , originally available on https://strudel.cc/?HNLRK5hZCBab
typeof setDefaultVoicings !== 'undefined' && setDefaultVoicings('legacy') // https://github.com/tidalcycles/strudel/pull/967
// "Cowrave"
// @license CC BY-NC-SA 4.0 https://creativecommons.org/licenses/by-nc-sa/4.0/
// cowbell by Felix Boehme – otherwise mostly "Caverave" @by Felix Roos
setcps(1)

const keys = x => x.s('sawtooth').cutoff(1200).gain(.5)
.attack(0).decay(.16).sustain(.3).release(.1);

const drums = stack(
s("bd*2").mask("<x@7 ~>/8").gain(.8),
s("~ <sd!7 [sd@3 ~]>").mask("<x@7 ~>/4").gain(.5),
s("[~ hh]*2").delay(.3).delayfeedback(.5).delaytime(.125).gain(.4),
s("cowbell cowbell").struct("2(3,8)").gain(10)
);

const synths = stack(

"<eb4 d4 c4 b3>/2"
.scale("<C:minor!3 C:melodic:minor>/2")
.struct("[~ x]*2")
.layer(
x=>x.scaleTranspose(0).early(0),
x=>x.scaleTranspose(2).early(1/8),
x=>x.scaleTranspose(7).early(1/4),
x=>x.scaleTranspose(8).early(3/8)
).note().apply(keys).mask("<~ x>/16")
.color('darkseagreen'),

note("<C2 Bb1 Ab1 [G1 [G2 G1]]>/2")
.struct("[x [~ x] <[~ [~ x]]!3 [x x]>@2]/2".fast(2))
.s('cowbell cowbell').attack(0.001).decay(0.2).sustain(1).cutoff(500)
.color('red'),
chord("<Cm7 Bb7 Fm7 G7b13>/2")
.struct("~ [x@0.2 ~]".fast(2))
.dict('lefthand').voicing()
.every(2, early(1/8))
.apply(keys).sustain(0)
.delay(.4).delaytime(.12)
.mask("<x@7 ~>/8".early(1/4))
).add(note("<-1 0>/8"))
stack(
drums.fast(2).color('orange'),
synths
).slow(2)
//.pianoroll({fold:1})

// "Bronski Beat - Smalltown Boy Cover"
// Based on the tutorials at https://strudel.cc/workshop/first-notes/#examples
// Borrowed from https://strudel.cc/?BVx2BSskV3b1#%2BIDFdClt%2BIDBdIDMgWzAgM10gW34gM10KW34gMF0gMiBbMCAyXSBbfiAyXQo%




// Basic mixer constants - we'll use them down the line
const _KICK_VOL = slider(0.432,0,1)
const _KICK_DIST = slider(2.467,1,4)

// Basic techno rythm - 4 on the floor
// sbd is short for soft bass drum
_$ : s("[sbd]*4")
  // let's add some nice distortion, volume adjusted and a visualization
  // this is picked up from the constants above
  .dist(_KICK_DIST)  // postgain : pattern
  .gain(_KICK_VOL)
  ._scope()
  // Sidechain kick to orbit 2,3,4
  .duck("2:3:4").duckattack(.2).duckdepth(.8)

// "Bassic" bassline
// 
$ : note("<[c2 c3]*4 [bb1 bb2]*4 [f2 f3]*4 [eb2 eb3]*4>")
.sound("gm_synth_bass_1")

// With a low-pass filter at 800Hz  
.lpf(800)
// Let's duck it under the kick  
.orbit(2)


let drums = s("bd*4, [~ <sd cp>]*2, [~ hh]*4")
  .bank("LinnLM1")
  .room(slider(0.826))

let bassline = note("<[c2 c3]*4 [bb1 bb2]*4 [f2 f3]*4 [eb2 eb3]*4>")
  .sound("gm_synth_bass_2")
  .lpf(800)
  .room(slider(0.826))

let lead = n(`<
[~ 0] 2 [0 2] [~ 2]
[~ 0] 1 [0 1] [~ 1]
[~ 0] 3 [0 3] [~ 3]
[~ 0] 2 [0 2] [~ 2]
>*4`).scale("C5:minor")
.sound("harp")
.lpf(2000)
.gain(1.25)
.room(slider(1))

stack(
  bassline,
  drums,
  arrange(
    [8, lead.mask(0)],
    [16, lead],
    [8, lead.mask(0)],
  )
)
.tscope({
  scale: .25,
  pos: .4,
  color: 'lightblue',
  smear: 0.85,
  thickness: 10,
})

// @version 1.0

// Some acid techno
// Code borrowed from amazing Switch Angel, see their video on https://www.youtube.com/watch?v=HkgV_-nJOuE&t=6s
// Small tweaks by AlienMind

// Tempo 120 bpm at 4/4
setCps(120/60/4)

// Basic mixer with slider
const BASS_VOL=slider(1,0,1)
const HIHATS_VOL=slider(0.441,0,1)
const PADS_VOL=slider(0.624,0,1)

// Other modifiers
const BASS_ENERGY=slider(1.048,0,8)

// 4 on the floor
$kick: s("[sbd]*4").dist("3:.3").gain(1)._scope()

// Sidechain kick to orbit 2,3,4 for pumping other overlapping instruments
.duck("2:3:4").duckattack(.2).duckdepth(.8)

// Random 303 bassline - not super random really, occasionally +1 octave
$bass: n(irand(2).almostNever(x=>x.add(7)).sub(7).seg(16)).scale("c:phrygian")._pianoroll()
// Make it repeatable
.rib(10,4)
// Heavy distortion
.dist("2:0.3")
// Nice tb303 with adjustable energy
.s("sawtooth").lpf(200).lpenv(BASS_ENERGY).lpq(12).gain(BASS_VOL)
// Make it pump with the duck
.orbit(2)

// Upbeats only
$hihats: s("[~ hh]*4").delay(0.1).gain(HIHATS_VOL)._scope()

// Subpad to keep it interesting, detuned, every 2 bars 
$subpad: s("supersaw").detune(1).rel(5).beat(2,32).slow(2).orbit(2)
.fm(slider(2,0,5)).fmh(slider(2.04,0,5)).room(1).roomsize(6).gain(PADS_VOL)

// Riser
$riser: s("pulse").orbit(4).seg(16).dec(.1).fm(time).fmh(time)

// Some Dark Electro by AlienMind
// Feel free to rip-off and cover it ;-)
setCpm(132/4)

// Bass drum - Kick
// It will duck the rest of the instruments to avoid interferences
// (duck + orbits down below)
$: s("bd!4").dist(slider(2.728,1,4)).duck("2:3:4").duckdepth(.1)
  .gain(slider(0.243))._scope()
// Basic drums - slider hi-hats, house downtempo hi-hat, claps
$: s("hh!16").gain(slider(0.162))
$: s("~ ~ hh ~").fast(4).delay(.2).gain(slider(0.314))
$: s("~ sd ~ sd").gain(slider(0.358)) 

// Lead
// Two oscilators, combining  wave table + sawtooth
// With longer decays (dec) we control the length of the notes
// The shorter, the pluckier
// We add diode distorsion
// Envelope controls the energy to give it an acid-techno vibe
// Trancegate provides a density in the pattern
$: n(irand(2).almostNever(x=>x.add(7)).sub(7).seg(16))  
  .ribbon(2,16)
  .scale("c:phrygian")
  .s("[wt_digital:1,sawtooth]!16")
  .wt(slider(0.823))
  .unison(2)
  .dec(slider(0.4483,.1,1))
  //.diode("3:.4")  
  .trancegate(slider(8.92,1,16),3,16)
  .acidenv(slider(0.729,0,1))
  .gain(slider(0.64))
  .o(2)._scope()

// Bass
$: note("[c4, c3]!16 [c#4, c#3]!16 [c4, c3]!16 [a#3, a#2]!8 [a3, a2]!8")
  .sound("supersaw")
  .slow(8)
  .gain(slider(0.702))
  .acidenv(slider(0.5))
  .o(3)._scope()
  ._punchcard()


// Pad
$: note("[c4, c3]!16 [c#4, c#3]!16 [c4, c3]!16 [a#3, a#2]!8 [a3, a2]!8")
  .sound("supersaw")
  .slow(8)  
  .room(0.6)
  .lpf(slider(2000,300,2000))
  .room(0.4)
  .postgain(slider(0.6778,.1,1))
  .o(4)._punchcard()

// Play external midi device
//$: note("[c4, c3]!16 [c#4, c#3]!16 [c4, c3]!16 [a#3, a#2]!8 [a3, a2]!8").slow(8).midi('3- UMC404HD 192k MIDI Out')

// Await MIDI control channel
// let cc = await midin('3- UMC404HD 192k MIDI In')

// Control low-pass filter with Midi CC 0
// Specific CC for knob needs to be manually found out
// $: note("c a f e").lpf(cc(0).range(0, 1000)).lpq(cc(1).range(0, 10)).sound("sawtooth")

// Master volume
all(x => x.mul(postgain(slider(1.214,1,2))))

// Set the global tempo a bit fast for the intense, running feel (around 135-150 BPM is typical)
// SetTempo(140)

// Tempo 120 bpm
setCps(120/60/4)

// Chord progression
const CHORD_PROGRESSION = "<Am!2 C!2 G Dm>"

// Perc
const KICKS_VOL=slider(0.49,0,1)
const SNARE_VOL=slider(0.49,0,1)
const HIHATS_VOL=slider(0.493,0,1)
const RHH_VOL=slider(0.59,0,1)

// Pads
const PADS_VOL=slider(0.363,0,1)

const ACID_VOL=slider(0,0,1)
const ACID_ENERGY=slider(5.952,0,8)

const BS_VOL=slider(0.442,0,1)
const ARP_VOL=slider(1,0,1)
const LEADS_VOL=slider(0,0,1)


const SUBPADS_VOL=slider(0.517,0,1)
const RISER_VOL=slider(0,0,1)

// Other modifiers

// 4 on the floor
$kick: s("bd*4")
  .bank("RolandTR909") // Use a heavy, punchy kick
  .dist("3:.3").gain(KICKS_VOL)._scope()
// Sidechain kick to orbit 2,3,4
.duck("2:3:4").duckattack(.2).duckdepth(.8)


// snare
snare: s("[~ sd]*2")
  .bank("RolandTR909") // Use a heavy, punchy kick
  .gain(SNARE_VOL)._scope()

$acid: n(irand(0).almostNever(x=>x.add(5)).sub(0).seg(16)).chord(CHORD_PROGRESSION).voicing()
  // Make it repeatable
  .rib(2,4)
  // Heavy distortion
  .dist("2:0.3")
  // Nice tb303 with adjustable energy
  .s("sawtooth").lpf(200).lpenv(ACID_ENERGY).lpq(12).gain(ACID_VOL)
  ._pianoroll()
  // Make it pump with the duck
  .orbit(2)



// Rolling hithats
$rollinghh: s("[hh]*16").gain(RHH_VOL)._scope()

// Upbeats only
$hihats: s("[~ hh]*4").delay(0.1).gain(HIHATS_VOL)._scope()

// Subpad to keep it interesting, detuned, every 2 bars
//$subpad: s("supersaw").chord(CHORD_PROGRESSION).voicing().detune(1).rel(5).beat(2,32).slow(2).orbit(2)
//.fm(slider(0,0,5)).fmh(slider(2.04,0,5)).room(1).roomsize(6).gain(SUBPADS_VOL)

$riser: s("pulse").orbit(4).seg(16).dec(.1).fm(time).fmh(time).gain(RISER_VOL)


$arp: n("0").chord(CHORD_PROGRESSION).voicing()
  .sound("supersaw")
  .lpf(slider(262,0,1000))
  .sustain(0.5).release(0.01).attack(0)
  .room(0.6)
  .lpenv(slider(4.00025,1.25,6))
  .postgain(ARP_VOL)
  .orbit(3)
  ._punchcard()



// Pads
$pads: s("supersaw").chord(CHORD_PROGRESSION).voicing().gain(PADS_VOL).orbit(3)._pianoroll()


// Bass
$bs: n("<0 <1 4 2 [2 1]>>*8").s("gm_acoustic_bass").chord(CHORD_PROGRESSION).voicing().gain(BS_VOL)._punchcard()

// Some fast trance
// Original content by Switch_Angel https://www.youtube.com/watch?v=GWXCCBsOMSg
// She's just amazing
setCpm(150/4)
//samples('local:')

setGainCurve(x => Math.pow(x,2))

register('trancegate', (density, seed, length, x) => {
    return x.struct(rand.mul(density).round().seg(16).rib(seed, length)).fill().clip(.7)
})

// quantize notes to given values: pat.grab("e:f#:c")
register('grab', function (scale, pat) {
    // Supports ':' list syntax in mininotation
    scale = (Array.isArray(scale) ? scale.flat() : [scale]).flatMap((val) =>
      typeof val === 'number' ? val : noteToMidi(val) - 48
    );
  
    return pat.withHap((hap) => {
      const isObject = typeof hap.value === 'object';
      let note = isObject ? hap.value.n : hap.value;
      if (typeof note === 'number') {
        note = note;
      }
      if (typeof note === 'string') {
        note = noteToMidi(note);
      }
  
      if (isObject) {
        delete hap.value.n; // remove n so it won't cause trouble
      }
      const octave = (note / 12) >> 0;
      const transpose = octave * 12;
  
      const goal = note - transpose;
      note =
        scale.reduce((prev, curr) => {
          return Math.abs(curr - goal) < Math.abs(prev - goal) ? curr : prev;
        }) + transpose;
  
      return hap.withValue(() => (isObject ? {...hap.value, note} : note));
    });
});

// lpf between 0 and 1
register('rlpf', (x,pat) => {return pat.lpf(pure(x).mul(12).pow(4))})

//hpf between 0 and 1
register('rhpf', (x,pat) => {return pat.hpf(pure(x).mul(12).pow(4))})

$: n("<3@3 4 5 @3 6>*2".add(-14)).scale("g:minor").
  s("supersaw").
  trancegate(1.5,45,1).
  orbit(2).
  rlpf(slider(0.571,0,1)).
  lpenv(2).
  gain(0.5)

$: s("~ hh ~ hh").fast(2).gain(0.5)

$: n("0@2 <-7 [-5 -2]>@3 <0 -3 2 1>@3".add(7))
  .scale("g:minor")
  .s("supersaw").trancegate(1.4,45,1).orbit(3)
  .delay(.7).pan(rand)
  .rlpf(slider(0.285)).lpenv(2)


$: s("sbd!4").almostNever(ply("2 | 4"))._scope()

// tb303 style filter envelope control between 0 & 1 values for useful range
register('acidenv', (x, pat) => pat.lpf(100)
  .lpenv(x * 9).lps(.2).lpd(.12).lpq(2)
)

setGainCurve(x => Math.pow(x, 2))


//tracker style arrangement
window.track = function(...input) {
  const patterns = input.shift()
  let mods = Array.isArray(input.at(-1)) ? input.pop() : undefined
  if (input.length % 2 !== 0) {
    throw new Error('Arrange needs a length paramter for each pattern (length, pattern, length, pattern)');
  }
  let sects = [];
  let total = 0;
  for (let i = 0; i < input.length; i += 2) {
    let inp = [input.at(i)].flat()
    let cycles = inp.at(0);
    let start = inp.at(1) ?? 0
    
    total += cycles;
    
    let cpat = input.at(i + 1).innerBind((str, pat) => {

      const pats = []
      str.split(/-+/).forEach((val, index) => {
        if (val == false ){
        return
        }
        let newPat = patterns.at(index)
         mods?.forEach(([mod, callback]) => {
            if (val != mod) {
              return
            }
            newPat = callback(newPat)
         })
        
          pats.push(newPat)
      })
      return stack(...pats)
    });
   
    sects.push([cycles, cpat.ribbon(start, cycles).fast(cycles)]);
  }
  return stepcat(...sects).slow(total);
}
/**
$: track(
   [bd,     sd,     hat,    clap,    bass], 
 2, "--------0------1-------1--------0",
 2, "1-------0------1-------D--------0",
 4, "1-------0------1-------1--------1",
  [['D' ,(x) => x.delay(.5)]] //Optional modifiers
)
*/


/**
 * Quick Arrange
 * Allows to arrange multiple patterns together over multiple cycles.
 * Takes a variable number of arrays with two elements specifying the number of cycles and the pattern to use.
 *
 * @return {Pattern}
 * @example
 * ar(
 *   4, "<c a f e>(3,8)",
 *   2, "<g a>(5,8)"
 * ).note()
 */
window.ar = function(...input) {

  if (input.length % 2 !== 0) {
    throw new Error('Arrange needs a length paramter for each pattern (length, pattern, length, pattern)');
  }
  let sects = [];
  let total = 0;
  for (let i = 0; i < input.length; i += 2) {
    let inp = [input.at(i)].flat()
    let cycles = inp.at(0);
    let start = inp.at(1) ?? 0
    total += cycles;
    
    let pattern = input.at(i + 1);
    sects.push([cycles, pattern.ribbon(start, cycles).fast(cycles)]);
  }
  return stepcat(...sects).slow(total);
}


window.p = stack

window.blockArrange = function (patArr, modifiers = []) {
  return stack(
    ...patArr.map(([pat, maskPat]) => {
      pat = [pat].flat()

      return maskPat.fmap(m => {
        return stack(...pat.map(p => {

          if (m == 0) {
            return
          }
          const ms = m.toString()
          let newPat = p

          if (ms.includes('R')) {
            newPat = newPat.restart(1)
          }
          if (ms.includes('B')) {
            newPat = newPat.rev().speed(-1)
          }
          modifiers.forEach(([mod, callback]) => {
            if (mod(ms)) {
              newPat = callback(newPat)
            }
          })
          return newPat
        }).filter(Boolean))
      }).innerJoin()
    }).flat()
  )
}

// example:
// $: blockArrange(
